        ("-v / -vv / -vvv", "More verbose logging.", "Debugging symbol problems."),
        ("-p, --plugin-dirs", "Extra plugin folders.", "Custom plugins."),
        ("-s, --symbol-dirs", "Extra symbol table folders.", "Offline labs and Linux/Mac symbols."),
