        ("--cache-path", "Where to cache data.", "Custom cache location."),
        ("--offline", "Do not download symbol tables.", "Lab without internet."),
        ("--remote-isf-url URL", "Use a remote symbol server.", "Custom symbols."),
        ("--parallelism MODE", "Use threads or processes.", "Speed."),
        ("--single-location URL", "Treat the file as one location.", "Special file layouts."),
        ("-l, --log FILE", "Write a log.", "Records."),
        ("-h, --help", "Help; `vol PLUGIN -h` shows plugin options.", "Reading a plugin's options."),
        ("windows.info / windows.pslist / windows.pstree / windows.psscan", "Basic system and process listing plugins.", "First steps."),
        ("windows.cmdline / windows.envars / windows.getsids", "Command lines, environment, owner SIDs.", "Understanding processes."),
        ("windows.netscan / windows.netstat", "Network connections.", "Finding C2 and sessions."),
        ("windows.dlllist / windows.handles / windows.ldrmodules", "DLLs and handles; hidden modules.", "Spotting injected code."),
        ("windows.malfind / windows.vadinfo", "Suspicious memory regions.", "Injection."),
        ("windows.dumpfiles / windows.memmap --dump / windows.pslist --dump", "Write files and process memory to disk.", "Extracting evidence."),
        ("windows.registry.hivelist / windows.registry.printkey", "Registry hives and keys.", "Persistence and settings."),
        ("windows.hashdump / windows.lsadump / windows.cachedump", "Password hashes and secrets.", "Credentials in a lab image."),
