        ("Analyze > Decode As", "Interpret a port as another protocol.", "Services on odd ports."),
        ("Analyze > Expert Information", "Warnings, retransmissions, errors.", "Finding trouble."),
        ("Telephony / Wireless menus", "VoIP calls, Wi-Fi details.", "Specialised captures."),
        ("-i INTERFACE", "Command line: capture from this interface.", "Live capture."),
        ("-k", "Start capturing immediately.", "Live capture."),
        ("-r FILE", "Open this file.", "Analysis."),
        ("-f FILTER", "Capture filter.", "Small files."),
        ("-Y FILTER", "Apply a display filter on open.", "Direct to the point."),
        ("-w FILE", "Write the capture to a file.", "Saving evidence."),
        ("-a / -b", "Autostop and ring-buffer conditions.", "Time limits."),
